// Load config from n8n variables or use defaults
const config = {
  domain: 'kahunaworkforce.com',
  semrush_api_key: $input.first().json.body?.semrush_api_key || '',
  database: 'us',
  ga4_property_id: $input.first().json.body?.ga4_property_id || '',
  tracked_keywords: $input.first().json.body?.tracked_keywords || [],
  slack_webhook_url: '',
  day_of_week: new Date().getDay() // 0=Sunday
};

// Try loading from n8n variables
try {
  config.slack_webhook_url = $vars.SLACK_WEBHOOK_URL || '';
  config.semrush_api_key = config.semrush_api_key || $vars.SEMRUSH_API_KEY || '';
} catch(e) {}

return [{ json: { ...config, run_site_audit: config.day_of_week === 1, timestamp: new Date().toISOString() } }];

// Compile daily position tracking report
const config = $('Load Config').first().json;
const overviewRaw = $('SEMrush: Domain Overview').first().json;
const historyRaw = $('SEMrush: Rank History').first().json;
const positionsRaw = $('SEMrush: Current Positions').first().json;

// Parse domain overview
let overview = {};
try {
  const text = typeof overviewRaw === 'string' ? overviewRaw : (overviewRaw.data || '');
  const lines = text.split('\n').filter(l => l.trim());
  if (lines.length > 1) {
    const vals = lines[1].split(';');
    overview = {
      domain: vals[0],
      rank: parseInt(vals[1] || 0),
      organic_keywords: parseInt(vals[2] || 0),
      organic_traffic: parseInt(vals[3] || 0),
      organic_cost: parseFloat(vals[4] || 0),
      paid_keywords: parseInt(vals[5] || 0),
      paid_traffic: parseInt(vals[6] || 0),
      paid_cost: parseFloat(vals[7] || 0)
    };
  }
} catch(e) { overview = { error: e.message }; }

// Parse position changes
let positions = [];
try {
  const text = typeof positionsRaw === 'string' ? positionsRaw : (positionsRaw.data || '');
  const lines = text.split('\n').filter(l => l.trim());
  if (lines.length > 1) {
    positions = lines.slice(1).map(line => {
      const vals = line.split(';');
      return {
        keyword: vals[0],
        position: parseInt(vals[1] || 0),
        previous_position: parseInt(vals[2] || 0),
        search_volume: parseInt(vals[3] || 0),
        difficulty: parseInt(vals[4] || 0),
        traffic: parseFloat(vals[5] || 0),
        url: vals[6] || ''
      };
    });
  }
} catch(e) { positions = [{ error: e.message }]; }

// Identify movers
const improved = positions.filter(p => p.previous_position > 0 && p.position < p.previous_position);
const declined = positions.filter(p => p.previous_position > 0 && p.position > p.previous_position);
const newRankings = positions.filter(p => p.previous_position === 0 && p.position > 0);
const lostRankings = positions.filter(p => p.position === 0 && p.previous_position > 0);

const report = {
  pipeline_step: 'daily_monitoring',
  domain: config.domain,
  generated_at: config.timestamp,
  domain_overview: overview,
  position_tracking: {
    total_tracked: positions.length,
    improved: improved.length,
    declined: declined.length,
    new_rankings: newRankings.length,
    lost_rankings: lostRankings.length,
    top_improvers: improved.sort((a,b) => (b.previous_position - b.position) - (a.previous_position - a.position)).slice(0, 10),
    top_decliners: declined.sort((a,b) => (b.position - b.previous_position) - (a.position - a.previous_position)).slice(0, 10),
    top_10_keywords: positions.filter(p => p.position <= 10).length,
    top_20_keywords: positions.filter(p => p.position <= 20).length
  },
  run_site_audit: config.run_site_audit
};

return [{ json: report }];

// Build Slack notification with monitoring results
const report = $('Compile Daily Report').first().json;
const config = $('Load Config').first().json;

let auditSection = '';
try {
  const auditData = $('SEMrush: Site Audit').first().json;
  auditSection = `\n\n:mag: *Weekly Site Audit*\n${typeof auditData === 'string' ? auditData.substring(0, 500) : JSON.stringify(auditData).substring(0, 500)}`;
} catch(e) {
  // No audit this run
}

const pt = report.position_tracking;
const ov = report.domain_overview;

const slackMessage = {
  text: `:chart_with_upwards_trend: *SEO Daily Report: ${report.domain}*\n_${new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}_`,
  blocks: [
    {
      type: 'header',
      text: { type: 'plain_text', text: `SEO Report: ${report.domain}` }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `:globe_with_meridians: *Domain Overview*\n• Organic Keywords: ${ov.organic_keywords?.toLocaleString() || 'N/A'}\n• Organic Traffic: ${ov.organic_traffic?.toLocaleString() || 'N/A'}\n• Domain Rank: ${ov.rank || 'N/A'}`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `:bar_chart: *Position Tracking*\n• Top 10 Keywords: ${pt.top_10_keywords}\n• Top 20 Keywords: ${pt.top_20_keywords}\n• :arrow_up: Improved: ${pt.improved} | :arrow_down: Declined: ${pt.declined}\n• :new: New: ${pt.new_rankings} | :x: Lost: ${pt.lost_rankings}`
      }
    }
  ]
};

if (pt.top_improvers.length > 0) {
  const improverText = pt.top_improvers.slice(0, 5).map(k => `• \"${k.keyword}\" ${k.previous_position} → ${k.position} (+${k.previous_position - k.position})`).join('\n');
  slackMessage.blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: `:star: *Top Improvers*\n${improverText}` }
  });
}

if (pt.top_decliners.length > 0) {
  const declinerText = pt.top_decliners.slice(0, 5).map(k => `• \"${k.keyword}\" ${k.previous_position} → ${k.position} (-${k.position - k.previous_position})`).join('\n');
  slackMessage.blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: `:warning: *Top Decliners*\n${declinerText}` }
  });
}

return [{ json: { report, slack_message: slackMessage } }];
